func TestJWTRefreshTokenCompatibility(t *testing.T) {
	if testing.Short() {
		t.Skip("Skipping integration test in short mode - requires both servers running")
	}

	// Generate a token using Go
	registerBody := map[string]interface{}{
		"email":    fmt.Sprintf("jwt-test-%d@example.com", time.Now().Unix()),
		"password": "testpassword123",
		"name":     "JWT Test User",
	}

	resp, body := makeJWTRequest(t, goAPIBaseURL+"/auth/register", "POST", registerBody, "")
	require.Equal(t, http.StatusCreated, resp.StatusCode)

	var result map[string]interface{}
	err := json.Unmarshal(body, &result)
	require.NoError(t, err)

	originalToken, ok := result["accessToken"].(string)
	require.True(t, ok)

	// Refresh the token using Go API
	refreshResp, refreshBody := makeJWTRequest(t, goAPIBaseURL+"/auth/refresh", "POST", nil, originalToken)
	assert.Equal(t, http.StatusOK, refreshResp.StatusCode)

	// Parse refresh response
	var refreshResult map[string]interface{}
	err = json.Unmarshal(refreshBody, &refreshResult)
	require.NoError(t, err)

	newToken, ok := refreshResult["accessToken"].(string)
	require.True(t, ok)
	require.NotEmpty(t, newToken)
	assert.NotEqual(t, originalToken, newToken, "Refreshed token should be different")

	// Verify the new token works with both systems
	goResp, _ := makeJWTRequest(t, goAPIBaseURL+"/auth/me", "GET", nil, newToken)
	assert.Equal(t, http.StatusOK, goResp.StatusCode)

	nextJSResp, _ := makeJWTRequest(t, nextJSAPIBaseURL+"/auth/me", "GET", nil, newToken)
	assert.Equal(t, http.StatusOK, nextJSResp.StatusCode)
}

// Helper functions

func makeJWTRequest(t *testing.T, url, method string, body map[string]interface{}, token string) (*http.Response, []byte) {
	var reqBody io.Reader
	if body != nil {
		jsonBody, err := json.Marshal(body)
		require.NoError(t, err)
		reqBody = bytes.NewBuffer(jsonBody)
	}

	req, err := http.NewRequest(method, url, reqBody)
	require.NoError(t, err)

	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}

	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	client := &http.Client{Timeout: 10 * time.Second}
	resp, err := client.Do(req)
	require.NoError(t, err)
	defer resp.Body.Close()

	respBody, err := io.ReadAll(resp.Body)
	require.NoError(t, err)

	return resp, respBody
}
